def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build value grid (1-indexed)
    val = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            val[y][x] = v

    # Edge case N == 1
    if N == 1:
        return val[1][1]

    INF_NEG = -10**15
    # dp_prev[x1][x2] : max sum after step k-1 (k starts from 2)
    dp_prev = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = val[1][1]  # start at (1,1) for both agents

    # Iterate over steps k = 3 .. 2N
    for k in range(3, 2 * N + 1):
        dp_curr = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        for x1 in range(1, N + 1):
            y1 = k - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(1, N + 1):
                y2 = k - x2
                if y2 < 1 or y2 > N:
                    continue

                best = INF_NEG
                # Enumerate previous positions: each agent moved either right or down
                for dx1 in (0, 1):          # dx1=1 -> moved right (x1-1), dx1=0 -> moved down (x1)
                    prev_x1 = x1 - dx1
                    if prev_x1 < 1:
                        continue
                    for dx2 in (0, 1):
                        prev_x2 = x2 - dx2
                        if prev_x2 < 1:
                            continue
                        prev_val = dp_prev[prev_x1][prev_x2]
                        if prev_val > best:
                            best = prev_val
                if best == INF_NEG:
                    continue

                addition = val[y1][x1]
                if x1 != x2 or y1 != y2:
                    addition += val[y2][x2]
                dp_curr[x1][x2] = best + addition
        dp_prev = dp_curr

    # The answer is when both agents reach (N,N)
    return dp_prev[N][N]

def cantor_numbering(N: int) -> str:
    # Find the diagonal (sum of indices) that contains the N-th fraction
    lo, hi = 2, 2
    while (hi - 1) * hi // 2 < N:
        hi <<= 1
    while lo < hi:
        mid = (lo + hi) // 2
        if (mid - 1) * mid // 2 >= N:
            hi = mid
        else:
            lo = mid + 1
    s = lo  # diagonal index sum
    prev_total = (s - 2) * (s - 1) // 2
    index_in_diag = N - prev_total - 1  # 0-based index within the diagonal
    if s % 2 == 0:  # diagonal goes from (s-1,1) to (1,s-1)
        numerator = s - 1 - index_in_diag
        denominator = index_in_diag + 1
    else:          # diagonal goes from (1,s-1) to (s-1,1)
        numerator = index_in_diag + 1
        denominator = s - numerator
    return f"{numerator}/{denominator}"

