def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    from itertools import combinations

    rows_available = list(range(1, M))   # possible horizontal aisle positions
    cols_available = list(range(1, N))   # possible vertical aisle positions

    # Precompute masks for each row and column
    row_masks = {}
    col_masks = {}

    # Assign an index to each chatting pair
    for r in rows_available:
        mask = 0
        for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
            if (x1 <= r < x2) or (x2 <= r < x1):
                mask |= (1 << idx)
        row_masks[r] = mask

    for c in cols_available:
        mask = 0
        for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
            if (y1 <= c < y2) or (y2 <= c < y1):
                mask |= (1 << idx)
        col_masks[c] = mask

    best_count = -1
    best_rows_choice = ()
    best_cols_choice = ()

    # If K or L is zero, handle empty combinations
    row_subsets = [()] if K == 0 else combinations(rows_available, K)
    col_subsets = [()] if L == 0 else combinations(cols_available, L)

    for rows_subset in row_subsets:
        rows_mask = 0
        for r in rows_subset:
            rows_mask |= row_masks[r]
        for cols_subset in col_subsets:
            mask = rows_mask
            for c in cols_subset:
                mask |= col_masks[c]
            # Count bits set
            try:
                cnt = mask.bit_count()
            except AttributeError:
                cnt = bin(mask).count('1')
            if cnt > best_count or (cnt == best_count and (rows_subset, cols_subset) < (best_rows_choice, best_cols_choice)):
                best_count = cnt
                best_rows_choice = rows_subset
                best_cols_choice = cols_subset

    row_str = ' '.join(map(str, best_rows_choice))
    col_str = ' '.join(map(str, best_cols_choice))
    return (row_str, col_str)

