def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    first = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if first:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)
        # Determine variable part
        if degree == 0:
            var_str = ''
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = f'x^{degree}'
        terms.append(f'{sign}{coeff_str}{var_str}')
        first = False
    return ''.join(terms) if terms else '0'

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # A complete cipher must map all 26 uppercase letters
    if len(mapping) < 26:
        return "Failed"

    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.
    """
    def helper(in_l: str, post_l: str) -> str:
        if not in_l:
            return ""
        if len(in_l) == 1:
            return in_l
        root = post_l[-1]
        idx = in_l.index(root)
        left_in = in_l[:idx]
        right_in = in_l[idx + 1 :]
        left_post = post_l[: len(left_in)]
        right_post = post_l[len(left_in) : -1]
        return root + helper(left_in, left_post) + helper(right_in, right_post)

    return helper(inorder, postorder)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    """
    if A == B:
        return 0
    from collections import deque
    max_steps = 10
    visited = {A}
    queue = deque([(A, 0)])
    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            i = 0
            while True:
                i = current.find(src, i)
                if i == -1:
                    break
                new_str = current[:i] + tgt + current[i+len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                i += 1
    return "NO ANSWER!"

def find_min_n_greater_than_k(k: int) -> int:
    """Find the smallest positive integer n such that the harmonic sum up to 1/n exceeds k."""
    import math
    # Euler–Mascheroni constant
    gamma = 0.57721566490153286060651209

    def harmonic_approx(n: int) -> float:
        """Approximate the n-th harmonic number using an asymptotic expansion."""
        if n == 0:
            return 0.0
        return math.log(n) + gamma + 1.0/(2*n) - 1.0/(12*n*n) + 1.0/(120*n**4)

    # Find an upper bound for the answer where the approximation already exceeds k
    low, high = 1, 1
    while harmonic_approx(high) <= k:
        high *= 2

    # Binary search for the smallest n whose harmonic sum exceeds k
    while low < high:
        mid = (low + high) // 2
        if harmonic_approx(mid) <= k:
            low = mid + 1
        else:
            high = mid

    # Verify the result by computing the real harmonic sum from 1 to low
    cumulative = 0.0
    for n in range(1, low + 1):
        cumulative += 1.0 / n
        if cumulative > k:
            return n
    return low

def is_prime(num: int) -> bool:
    """Determine whether a given integer is a prime number."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, stmts in statements.items():
        is_liar = participant in liar_count
        for st in stmts:
            # ignore statements that mention a day of the week
            st_upper = st.upper()
            if any(day in st_upper for day in days_of_week):
                continue

            # normalize statement for easier parsing
            cleaned = st.strip().rstrip('.').strip()
            cleaned_lower = cleaned.lower()

            # determine truth value of the statement
            truth = None
            if cleaned_lower.startswith("i am guilty"):
                truth = scenario == participant
            elif cleaned_lower.startswith("i am not guilty"):
                truth = scenario != participant
            else:
                if " is not guilty" in cleaned_lower:
                    subject = cleaned_lower.split(" is not guilty")[0].strip().upper()
                    truth = scenario != subject
                elif " is guilty" in cleaned_lower:
                    subject = cleaned_lower.split(" is guilty")[0].strip().upper()
                    truth = scenario == subject

            # if the statement does not pertain to guilt, ignore it
            if truth is None:
                continue

            # check consistency based on liar status
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False
    return True

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        for cap in range(T, time - 1, -1):
            new_val = dp[cap - time] + value
            if new_val > dp[cap]:
                dp[cap] = new_val
    return max(dp)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True
    max_filled = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_filled = j
            break
    return V - max_filled

def calculate_arrangements(n, m, a) -> int:
    MOD = 1000007
    if m == 0:
        return 1
    if sum(a) < m:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for limit in a:
        # Prefix sums of current dp
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD
        new_dp = [0] * (m + 1)
        for s in range(m + 1):
            if s - limit - 1 >= 0:
                val = prefix[s] - prefix[s - limit - 1]
            else:
                val = prefix[s]
            new_dp[s] = val % MOD
        dp = new_dp
    return dp[m] % MOD

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    # Longest increasing subsequence ending at each position
    lis = [1] * n
    for i in range(n):
        hi = heights[i]
        for j in range(i):
            if heights[j] < hi and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    # Longest increasing subsequence in reversed array (will give longest decreasing subsequence starting at each position)
    rev = heights[::-1]
    lis_rev = [1] * n
    for i in range(n):
        hi = rev[i]
        for j in range(i):
            if rev[j] < hi and lis_rev[j] + 1 > lis_rev[i]:
                lis_rev[i] = lis_rev[j] + 1
    lds = [0] * n
    for i in range(n):
        lds[i] = lis_rev[n - 1 - i]
    # Compute longest bitonic subsequence length
    max_len = 0
    for i in range(n):
        cur_len = lis[i] + lds[i] - 1
        if cur_len > max_len:
            max_len = cur_len
    # Minimum deletions
    return n - max_len
